def main():
    base = idaapi.get_imagebase()
    ok = made = bad = 0
    for rva, kind, name, cmt in SYMS:
        ea = base + rva
        if kind == 'function':
            f = ida_funcs.get_func(ea)
            if f is None or f.start_ea != ea:
                if f is None and ida_funcs.add_func(ea):
                    made += 1
            f = ida_funcs.get_func(ea)
            if f is not None and f.start_ea == ea:
                idc.set_func_cmt(ea, cmt, 0)
            else:
                idc.set_cmt(ea, cmt, 0)
        else:
            idc.set_cmt(ea, cmt, 0)
        if idc.set_name(ea, name, idc.SN_NOWARN | idc.SN_NOCHECK):
            ok += 1
        else:
            bad += 1
            print('N3: could not name 0x%x %s' % (rva, name))
    if STRUCTS:
        n = idc.parse_decls(STRUCTS, idc.PT_SILENT)
        print('N3: struct declarations parsed, errors=%s' % n)
    print('N3: named %d, functions created %d, failed %d' % (ok, made, bad))

main()
